export function t(key, locale) {
  const l = locale && DICT[locale] ? locale : 'fr';
  return DICT[l][key] ?? DICT.fr[key] ?? key;
}

// Langue déduite du pays saisi à l'inscription (docx « derniers ajouts »,
// 05/09/2026 : « si l'utilisateur met pays France alors tu mets la langue
// française, pareil si c'est UK alors anglais, etc. »). Le champ pays est un
// texte libre, donc on reconnaît le nom du pays écrit dans n'importe laquelle
// des 7 langues de l'app (et les codes ISO courants), sans accents ni casse.
// Renvoie null si le pays n'est pas reconnu : on ne change alors rien.
const COUNTRY_LOCALE = [
  ['fr', ['france', 'fr', 'fra', 'belgique', 'belgium', 'belgie', 'belgien', 'suisse', 'switzerland', 'schweiz', 'svizzera', 'luxembourg', 'monaco', 'quebec', 'senegal', 'cote d ivoire', 'ivory coast', 'maroc', 'morocco', 'tunisie', 'tunisia', 'algerie', 'algeria', 'cameroun', 'cameroon', 'madagascar', 'la reunion', 'reunion', 'guadeloupe', 'martinique', 'guyane', 'nouvelle caledonie', 'polynesie']],
  ['en', ['uk', 'u k', 'gb', 'united kingdom', 'royaume uni', 'great britain', 'grande bretagne', 'england', 'angleterre', 'scotland', 'ecosse', 'wales', 'northern ireland', 'ireland', 'irlande', 'usa', 'u s a', 'us', 'united states', 'united states of america', 'etats unis', 'america', 'australia', 'australie', 'australien', 'new zealand', 'nouvelle zelande', 'canada', 'kanada', 'south africa', 'afrique du sud', 'singapore', 'singapour', 'india', 'inde', 'hong kong', 'malta', 'malte']],
  ['de', ['deutschland', 'germany', 'allemagne', 'germania', 'alemania', 'alemanha', 'duitsland', 'de', 'deu', 'osterreich', 'oesterreich', 'austria', 'autriche', 'liechtenstein']],
  ['it', ['italia', 'italy', 'italie', 'italien', 'it', 'ita', 'san marino', 'saint marin']],
  ['es', ['espana', 'spain', 'espagne', 'spanien', 'spagna', 'es', 'esp', 'mexico', 'mexique', 'argentina', 'argentine', 'chile', 'chili', 'colombia', 'colombie', 'peru', 'perou', 'uruguay', 'venezuela', 'ecuador', 'equateur', 'bolivia', 'bolivie', 'paraguay', 'costa rica', 'panama', 'guatemala', 'republica dominicana', 'republique dominicaine']],
  ['pt', ['portugal', 'pt', 'prt', 'brasil', 'brazil', 'bresil', 'brasilien', 'brasile', 'angola', 'mocambique', 'mozambique', 'cabo verde', 'cap vert']],
  ['nl', ['nederland', 'netherlands', 'pays bas', 'niederlande', 'paesi bassi', 'paises bajos', 'holland', 'hollande', 'nl', 'nld', 'vlaanderen', 'flandre']],
];

export function localeForCountry(country) {
  if (!country) return null;
  const norm = String(country)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z]+/g, ' ')
    .trim();
  if (!norm) return null;
  for (const [loc, names] of COUNTRY_LOCALE) {
    if (names.includes(norm)) return loc;
  }
  return null;
}

function detectBrowserLocale() {
  if (typeof navigator === 'undefined') return 'fr';
  const langs = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language];
  for (const raw of langs) {
    const short = (raw || '').slice(0, 2).toLowerCase();
    if (LOCALES.includes(short)) return short;
  }
  return 'fr';
}

// Hook client : lit la préférence enregistrée (localStorage), sinon détecte
// la langue du navigateur, sinon retombe sur le français. Toutes les
// instances de ce hook dans l'app se synchronisent entre elles (même onglet)
// via un événement custom 'aaron-locale-change', pour que changer la langue
// dans un composant (ex: le sélecteur dans la barre latérale) mette
// immédiatement à jour tous les autres textes traduits affichés ailleurs
// dans la page sans recharger.
export function useLocale() {
  const [locale, setLocaleState] = useState('fr');

  useEffect(() => {
    try {
      const stored = window.localStorage.getItem(STORAGE_KEY);
      setLocaleState(stored && LOCALES.includes(stored) ? stored : detectBrowserLocale());
    } catch {
      setLocaleState(detectBrowserLocale());
    }

    function onChange(e) {
      if (e.detail && LOCALES.includes(e.detail)) setLocaleState(e.detail);
    }
    window.addEventListener('aaron-locale-change', onChange);
    return () => window.removeEventListener('aaron-locale-change', onChange);
  }, []);

  function setLocale(next) {
    if (!LOCALES.includes(next)) return;
    try {
      window.localStorage.setItem(STORAGE_KEY, next);
    } catch {
      // Stockage indisponible (navigation privée, etc.) : le changement
      // reste appliqué pour la session en cours via l'événement ci-dessous.
    }
    window.dispatchEvent(new CustomEvent('aaron-locale-change', { detail: next }));
  }

  return [locale, setLocale];
}
